  'spotter3d.pureAudio': 'pure-audio',
  'spotter3d.whatAfterPure': 'spotter: instead of talking, it places a soft sound at the position of each car near you, as if the car were really there in space. It is your audible "peripheral vision" in corners, overtakes, and side-by-side battles.',
  'spotter3d.howTitle': 'How it works',
  'spotter3d.howText': 'iRacing telemetry reports where nearby cars are. The app converts this into positioned sounds (HRTF): left sounds on the left, right sounds on the right, behind sounds lower-pitched, and nearer cars get louder. With no nearby cars, it stays silent.',
