  'spotter3d.useText': 'It comes on by default and runs on its own on any screen. Because of a browser rule, audio unlocks only after your first click anywhere in the app ? after that it works for the rest of the session. Put on headphones, adjust the volume below, and test the positioning with the buttons.',
