function patchViewText(language: ResolvedLanguage, patches: Record<string, Partial<ViewText>>): void {
  for (const [id, patch] of Object.entries(patches)) {
    VIEW_TEXT[language][id] = {
      ...(VIEW_TEXT[language][id] ?? {}),
      ...patch
    }
  }
}

